def treediff(a, b, path="root"):
    if hash(a) == hash(b):
        return None
    if type(a) is not type(b):
        return f"{path}: type {type(a).__name__} vs {type(b).__name__}\n  A={str(a)[:200]}\n  B={str(b)[:200]}"
    if len(a.children) != len(b.children):
        return f"{path}: nchildren {len(a.children)} vs {len(b.children)}\n  A={str(a)[:200]}\n  B={str(b)[:200]}"
    if len(a.children) == 0:
        return f"{path}: leaf differs\n  A={str(a)[:300]} {a.domains}\n  B={str(b)[:300]} {b.domains}"
    for i, (ca, cb) in enumerate(zip(a.children, b.children)):
        d = treediff(ca, cb, path + f".c{i}")
